# ১) কাঁচা Ordinal quality স্কোর থেকে Binary Target তৈরি: y = 1{q >= 6}
quality = [3, 4, 5, 6, 7, 8]
positive = []
for q in quality:
    if q >= 6:
        positive.append(1)
    else:
        positive.append(0)

print("Raw quality:", quality)
print("Binary y (q >= 6):", positive)

# ২) Split ভেদে Prevalence ও Majority Baseline Accuracy তুলনা
splits = [
    ("Decision", 163, 313),
    ("Final Test", 191, 320),
]
for name, pos, total in splits:
    prevalence = pos / total
    if prevalence >= 0.5:
        maj_acc = prevalence
    else:
        maj_acc = 1.0 - prevalence
    print(f"{name:10s} | Prevalence={prevalence:.4f} | MajorityAcc={maj_acc:.4f}")

# ১) তিনটি Split Role-এ Group Isolation যাচাই (শূন্য Overlap!)
fit_groups = {"G01", "G02", "G03", "G04", "G05"}
decision_groups = {"G06", "G07"}
test_groups = {"G08", "G09"}

assert fit_groups.isdisjoint(decision_groups), "Fit vs Decision overlap!"
assert fit_groups.isdisjoint(test_groups), "Fit vs Test overlap!"
assert decision_groups.isdisjoint(test_groups), "Decision vs Test overlap!"

total_unique = len(fit_groups | decision_groups | test_groups)
print("Zero overlap verified! Total unique groups:", total_unique)

# ২) Fit Role-এর ভেতরে 3-Fold CV-তেও Group Overlap শূন্য হওয়া বাধ্যতামূলক
cv_folds = [{"G01", "G02"}, {"G03", "G04"}, {"G05"}]
for i in range(len(cv_folds)):
    for j in range(i + 1, len(cv_folds)):
        assert cv_folds[i].isdisjoint(cv_folds[j]), "CV fold group leakage!"
print("All 3 inner CV folds are pairwise group-disjoint.")

from pathlib import Path
import hashlib, json

folder = Path("build/chapter-14-artifacts")
if (folder / "checksums.json").exists():
    hashes = json.loads((folder / "checksums.json").read_text())
    assert all(
        hashlib.sha256((folder / name).read_bytes()).hexdigest() == digest
        for name, digest in hashes.items()
    )
    print("Artifact bytes match the recorded manifest")
else:
    print("Run the documented CLI with --artifact-dir to generate artifacts first")

groups = {"A": {"tp": 8, "fn": 2}, "B": {"tp": 2, "fn": 3}}
recalls = {}
for group, counts in groups.items():
    positives = counts["tp"] + counts["fn"]
    # Missing positives means undefined recall, not evidence of zero performance.
    recalls[group] = counts["tp"] / positives if positives else None
print(recalls["A"], recalls["B"], recalls["A"] - recalls["B"])

import json
import math

# ১) Order Guard: কলামের নাম ও নিখুঁত ক্রম যাচাই
def validate_order(incoming, expected):
    if incoming != expected:
        raise ValueError("feature order mismatch")

try:
    validate_order(["pH", "alcohol"], ["alcohol", "pH"])
except ValueError as err:
    print("Order Guard caught:", err)

# ২) স্বয়ংসম্পূর্ণ JSON Inference Artifact ও Round-trip + Failure Drill যাচাই (Pure Python!)
artifact = {
    "features": ["a", "b"],
    "mean": [10.0, 1.0],
    "scale": [2.0, 1.0],
    "weights": [0.5, -1.0],
    "bias": 0.2,
    "threshold": 0.4,
}

def stable_sigmoid(score):
    if score >= 0.0:
        return 1.0 / (1.0 + math.exp(-score))
    z = math.exp(score)
    return z / (1.0 + z)

def predict_bundle(bundle, names, row):
    validate_order(names, bundle["features"])
    if len(row) != len(names):
        raise ValueError("Feature count mismatch")
    logit = bundle["bias"]
    for i in range(len(names)):
        val = float(row[i])
        sc = float(bundle["scale"][i])
        if (not math.isfinite(val)) or sc <= 0.0:
            raise ValueError("Invalid feature value or non-positive scale")
        z = (val - float(bundle["mean"][i])) / sc
        logit += z * float(bundle["weights"][i])
    prob = stable_sigmoid(logit)
    decision = 1 if prob >= float(bundle["threshold"]) else 0
    return prob, decision

# JSON Round-trip পরীক্ষা (allow_nan=False)
restored = json.loads(json.dumps(artifact, allow_nan=False))
p_orig, d_orig = predict_bundle(artifact, ["a", "b"], [12.0, 2.0])
p_rest, d_rest = predict_bundle(restored, ["a", "b"], [12.0, 2.0])
assert abs(p_orig - p_rest) <= 1e-12 and d_orig == d_rest

# Failure Drill: ভুল ক্রম ও NaN প্রত্যাখ্যান হচ্ছে কি না যাচাই
rejected_order = 0
try:
    predict_bundle(restored, ["b", "a"], [2.0, 12.0])
except ValueError:
    rejected_order = 1

rejected_nan = 0
try:
    predict_bundle(restored, ["a", "b"], [float("nan"), 2.0])
except ValueError:
    rejected_nan = 1

print(f"Round-trip OK -> p={p_rest:.6f}, decision={d_rest} | Rejected order={rejected_order}, nan={rejected_nan}")

